from __future__ import annotations

from exo import *
from exo.libs.memories import DRAM
from exo.API_scheduling import *

# ---------------------------------------------------------------------------
# Baseline matrix-matrix multiplication:
#   C[M, N] = A[M, K] * B[K, N]
#
# This is written in a clear, straightforward way first, then optimized
# using Exo scheduling primitives below.
# ---------------------------------------------------------------------------
@proc
def mm_base(
    M: size,
    N: size,
    K: size,
    A: DATA_TYPE[M, K] @ DRAM,
    B: DATA_TYPE[K, N] @ DRAM,
    C: DATA_TYPE[M, N] @ DRAM,
):
    assert M >= 1 and N >= 1 and K >= 1

    # Initialize C to zero.
    for i in seq(0, M):
        for j in seq(0, N):
            C[i, j] = 0.0

    # Compute C = A * B using an i-k-j loop order.
    # The innermost loop is over j so that:
    #   - B[k, j] is accessed with unit stride in memory
    #   - C[i, j] is also accessed with unit stride
    #   - A[i, k] is reused across the entire j-tile
    for i in seq(0, M):
        for k in seq(0, K):
            for j in seq(0, N):
                C[i, j] += A[i, k] * B[k, j]


# ---------------------------------------------------------------------------
# Scheduling for mm_base.
#
# We improve data locality and expose parallelism as follows:
#   1. Tile the j loop of the compute phase to work on contiguous blocks
#      of columns at a time (good for caches and SIMD).
#   2. Parallelize the outer i loop of the compute phase (row-wise
#      parallelism) using OpenMP-style parallelization.
#   3. Run a simplification pass to clean up any algebraic clutter
#      introduced by tiling and guards.
#
# The zero-initialization loop is left as-is because it is already
# cache-friendly (i outer, j inner).
# ---------------------------------------------------------------------------

mm_sched = mm_base

# Tile the second 'j' loop (the j loop in the compute phase). We use a
# fixed tile size and rely on a guarded tail to handle arbitrary N.
J_TILE = 32
mm_sched = divide_loop(mm_sched, "j #1", J_TILE, ("jo", "ji"), tail="guard")

# Parallelize the second 'i' loop (the outer loop of the compute phase).
# Each iteration operates on a distinct row of C and A, so there are
# no cross-iteration dependencies.
mm_sched = parallelize_loop(mm_sched, "i #1")

# Simplify the resulting code to remove redundant control and strength-reduce
# expressions created by the transformations above.
mm_sched = simplify(mm_sched)

# Expose the scheduled matmul kernel under a descriptive name.
mm_3mm = rename(mm_sched, "mm_3mm")


