# Top-level 3mm kernel: perform three matrix multiplications
#
#   E[ni, nj] = A[ni, nk] * B[nk, nj]
#   F[nj, nl] = C[nj, nm] * D[nm, nl]
#   G[ni, nl] = E[ni, nj] * F[nj, nl]
#
# Each multiplication is delegated to the optimized mm_3mm kernel above.
# This preserves the original 3mm computation while reusing the
# high-performance matmul implementation.
# ---------------------------------------------------------------------------
@proc
def kernel_3mm(
    ni: size,
    nj: size,
    nk: size,
    nl: size,
    nm: size,
    E: DATA_TYPE[ni, nj] @ DRAM,
    A: DATA_TYPE[ni, nk] @ DRAM,
    B: DATA_TYPE[nk, nj] @ DRAM,
    F: DATA_TYPE[nj, nl] @ DRAM,
    C: DATA_TYPE[nj, nm] @ DRAM,
    D: DATA_TYPE[nm, nl] @ DRAM,
    G: DATA_TYPE[ni, nl] @ DRAM,
