    # First multiplication: E = A * B
    mm_3mm(ni, nj, nk, A, B, E)

    # Second multiplication: F = C * D
    mm_3mm(nj, nl, nm, C, D, F)

    # Third multiplication: G = E * F
    mm_3mm(ni, nl, nj, E, F, G)

