        for j in seq(0, nj):
            E[i, j] = 0.0

    # E := A * B  (ni x nj = (ni x nk) * (nk x nj))
    # Inner-most loop over j → contiguous accesses to rows of B and E.
    for i in seq(0, ni):
        for k in seq(0, nk):
            for j in seq(0, nj):
                E[i, j] += A[i, k] * B[k, j]

