    # Row-panel GEMM: E[iE, jE] += A[iE, kE] * B[kE, jE]
    #   iE: row of A/E
    #   kE: inner dimension, iterating along A's contiguous dimension
    #   jE: column of B/E, kept innermost for good locality in B/E
    for iE in seq(0, ni):
        for kE in seq(0, nk):
            for jE in seq(0, nj):
